// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/terminal/FindShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Find & copy: a terminal's find bar, ported from the app's Terminal
 * (src/terminal/Terminal.tsx, the term-find-bar) with its search working on
 * the captured screen the way xterm's search addon does there: a plain,
 * case-insensitive match unless Aa is on, every match marked with the app's
 * find decorations and the current one brighter, Enter for the next match,
 * Shift+Enter for the previous one, Esc or × to close. ⌘F (Ctrl+F) in the
 * terminal opens it again, filled with the first line of the selection.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { ChevronDown, ChevronUp, X } from "lucide-react";
import { CaptureTile, MarkedScreen, plainText, useCapture, type Mark } from "./parts";
import { TileShot } from "./frames";

// The app's find decorations (FIND_DECORATIONS in Terminal.tsx).
const MATCH_BACKGROUND = "#66592c";
const ACTIVE_MATCH_BACKGROUND = "#a68b2e";

const QUERY = "notes";
// The scene is one Enter in: the second of the matches is the current one.
const INITIAL_MATCH = 1;

/** Every match of `query` in the screen's lines, in buffer order. */
function findMatches(lines: string[], query: string, caseSensitive: boolean): Mark[] {
  if (!query) return [];
  const needle = caseSensitive ? query : query.toLowerCase();
  const matches: Mark[] = [];
  lines.forEach((text, line) => {
    const haystack = caseSensitive ? text : text.toLowerCase();
    for (let start = haystack.indexOf(needle); start >= 0; start = haystack.indexOf(needle, start + needle.length)) {
      matches.push({ line, start, end: start + needle.length, style: {} });
    }
  });
  return matches;
}

function FindTile() {
  const lines = useCapture("api-86");
  const text = useMemo(() => lines.map(plainText), [lines]);
  const [open, setOpen] = useState(true);
  const [query, setQuery] = useState(QUERY);
  const [caseSensitive, setCaseSensitive] = useState(false);
  const [current, setCurrent] = useState(INITIAL_MATCH);
  const input = useRef<HTMLInputElement>(null);
  const host = useRef<HTMLSpanElement>(null);

  const matches = open ? findMatches(text, query, caseSensitive) : [];
  const index = matches.length ? Math.min(current, matches.length - 1) : -1;
  const step = (by: number) => {
    if (matches.length) setCurrent((index + by + matches.length) % matches.length);
  };
  const close = () => {
    setOpen(false);
    setQuery("");
    setCurrent(0);
  };

  // ⌘F (Ctrl+F off the Mac) after a press in this terminal opens the bar,
  // seeded with the first line of what is selected there.
  useEffect(() => {
    const term = host.current?.parentElement;
    if (!term) return;
    let armed = false;
    const press = (event: PointerEvent) => {
      armed = event.target instanceof Node && term.contains(event.target);
    };
    const key = (event: KeyboardEvent) => {
      const find = event.key.toLowerCase() === "f" && !event.altKey && !event.shiftKey && (event.metaKey || event.ctrlKey);
      if (!armed || !find) return;
      event.preventDefault();
      const selection = window.getSelection();
      const inside = selection?.anchorNode && term.contains(selection.anchorNode);
      setQuery(inside ? (selection.toString().split("\n")[0] ?? "").slice(0, 200) : "");
      setCurrent(0);
      setOpen(true);
      window.setTimeout(() => {
        input.current?.focus();
        input.current?.select();
      }, 0);
    };
    document.addEventListener("pointerdown", press, true);
    document.addEventListener("keydown", key);
    return () => {
      document.removeEventListener("pointerdown", press, true);
      document.removeEventListener("keydown", key);
    };
  }, []);

  const marks = matches.map((match, i) => ({ ...match, style: { bg: i === index ? ACTIVE_MATCH_BACKGROUND : MATCH_BACKGROUND } }));
  return (
    <CaptureTile id="api" kbd="⌘1">
      <MarkedScreen lines={lines} marks={marks} />
      <span ref={host} hidden />
      {open ? (
        <div className="term-find-bar" role="search">
          <input
            ref={input}
            className="term-find-input"
            value={query}
            placeholder="Find"
            aria-label="Find in terminal"
            spellCheck={false}
            onChange={(event) => {
              setQuery(event.target.value.slice(0, 200));
              setCurrent(0);
            }}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                step(event.shiftKey ? -1 : 1);
              } else if (event.key === "Escape") {
                event.preventDefault();
                close();
              }
            }}
          />
          <button
            type="button"
            className={`tile-btn ${caseSensitive ? "tile-btn-on" : ""}`}
            title={caseSensitive ? "Case sensitive on" : "Case sensitive off"}
            aria-label={caseSensitive ? "Case sensitive on" : "Case sensitive off"}
            aria-pressed={caseSensitive}
            onClick={() => {
              setCaseSensitive((value) => !value);
              setCurrent(0);
            }}
          >
            <span className="term-find-aa">Aa</span>
          </button>
          <button type="button" className="tile-btn" title="Previous match (Shift+Enter)" aria-label="Previous match" onClick={() => step(-1)}>
            <ChevronUp size={13} />
          </button>
          <button type="button" className="tile-btn" title="Next match (Enter)" aria-label="Next match" onClick={() => step(1)}>
            <ChevronDown size={13} />
          </button>
          <span className="term-find-count" role="status">
            {query && !matches.length ? "No matches" : index >= 0 ? `${index + 1} / ${matches.length}` : ""}
          </span>
          <button type="button" className="tile-btn" title="Close find (Esc)" aria-label="Close find" onClick={close}>
            <X size={13} />
          </button>
        </div>
      ) : null}
    </CaptureTile>
  );
}

export function FindShot() {
  return <TileShot backdrop="usage" session="api" tile={<FindTile key="api" />} />;
}
